class Solution {
public:
    int divisorSubstrings(int num, int k) {
        string s = to_string(num);
        int beauty = 0;
        for (int r = k - 1; r < (int)s.size(); r++) {
            int l = r - k + 1;
            int part = stoi(s.substr(l, k));
            if (part != 0 && num % part == 0) beauty++;
        }
        return beauty;
    }
};
